import json
from datetime import datetime

# Load analysis data
with open('/app/output/analysis_data.json', 'r') as f:
    data = json.load(f)

summary = data['summary']
location_summary = data['location_summary']
timeslot_summary = data['timeslot_summary']
vehicle_summary = data['vehicle_summary']
queue_heatmap = data['queue_heatmap']
wait_heatmap = data['wait_heatmap']
renewable_weather = data['renewable_weather']
price_by_slot = data['price_by_slot']
station_utilization = data['station_utilization']

# Generate HTML Report
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>EV Charging Network Performance & Grid Optimization Analytics Report</title>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <style>
        * {{
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }}
        body {{
            font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, Roboto, Oxygen, Ubuntu, sans-serif;
            line-height: 1.6;
            color: #1a1a2e;
            background: #f5f7fa;
        }}
        .report-container {{
            max-width: 1400px;
            margin: 0 auto;
            padding: 20px;
        }}
        .header {{
            background: linear-gradient(135deg, #0f4c75 0%, #3282b8 100%);
            color: white;
            padding: 40px;
            border-radius: 12px;
            margin-bottom: 30px;
            box-shadow: 0 10px 30px rgba(15, 76, 117, 0.3);
        }}
        .header h1 {{
            font-size: 2.2em;
            margin-bottom: 10px;
            font-weight: 600;
        }}
        .header .subtitle {{
            opacity: 0.9;
            font-size: 1.1em;
        }}
        .header .meta {{
            margin-top: 20px;
            font-size: 0.9em;
            opacity: 0.8;
        }}
        .kpi-banner {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            gap: 20px;
            margin-bottom: 30px;
        }}
        .kpi-card {{
            background: white;
            padding: 25px;
            border-radius: 12px;
            box-shadow: 0 4px 15px rgba(0,0,0,0.08);
            transition: transform 0.2s, box-shadow 0.2s;
        }}
        .kpi-card:hover {{
            transform: translateY(-3px);
            box-shadow: 0 8px 25px rgba(0,0,0,0.12);
        }}
        .kpi-card .label {{
            font-size: 0.85em;
            color: #6c757d;
            text-transform: uppercase;
            letter-spacing: 0.5px;
            margin-bottom: 8px;
        }}
        .kpi-card .value {{
            font-size: 2em;
            font-weight: 700;
            color: #1a1a2e;
        }}
        .kpi-card .detail {{
            font-size: 0.85em;
            color: #6c757d;
            margin-top: 8px;
        }}
        .kpi-card.highlight {{
            border-left: 4px solid #3282b8;
        }}
        .kpi-card.warning {{
            border-left: 4px solid #f39c12;
        }}
        .kpi-card.success {{
            border-left: 4px solid #27ae60;
        }}
        .section {{
            background: white;
            padding: 30px;
            border-radius: 12px;
            margin-bottom: 25px;
            box-shadow: 0 4px 15px rgba(0,0,0,0.08);
        }}
        .section h2 {{
            color: #0f4c75;
            font-size: 1.5em;
            margin-bottom: 25px;
            padding-bottom: 12px;
            border-bottom: 2px solid #e9ecef;
        }}
        .section h3 {{
            color: #3282b8;
            font-size: 1.15em;
            margin: 20px 0 15px 0;
        }}
        .section p {{
            color: #495057;
            margin-bottom: 15px;
        }}
        .chart-grid {{
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(400px, 1fr));
            gap: 25px;
            margin: 20px 0;
        }}
        .chart-container {{
            background: #f8f9fa;
            padding: 20px;
            border-radius: 10px;
            height: 320px;
        }}
        .heatmap-container {{
            overflow-x: auto;
            margin: 20px 0;
        }}
        table {{
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
            font-size: 0.95em;
        }}
        th {{
            background: #0f4c75;
            color: white;
            padding: 14px 12px;
            text-align: left;
            font-weight: 600;
        }}
        td {{
            padding: 12px;
            border-bottom: 1px solid #e9ecef;
        }}
        tr:hover {{
            background: #f8f9fa;
        }}
        .takeaway {{
            background: linear-gradient(135deg, #e8f4f8 0%, #d4eef7 100%);
            border-left: 4px solid #3282b8;
            padding: 15px 20px;
            margin: 15px 0;
            border-radius: 0 8px 8px 0;
        }}
        .takeaway-title {{
            font-weight: 600;
            color: #0f4c75;
            margin-bottom: 5px;
        }}
        .badge {{
            display: inline-block;
            padding: 4px 12px;
            border-radius: 15px;
            font-size: 0.8em;
            font-weight: 600;
        }}
        .badge-peak {{ background: #e74c3c; color: white; }}
        .badge-offpeak {{ background: #27ae60; color: white; }}
        .badge-midpeak {{ background: #f39c12; color: white; }}
        .toc {{
            background: #f8f9fa;
            padding: 25px;
            border-radius: 10px;
            margin-bottom: 30px;
        }}
        .toc h3 {{
            margin-top: 0 !important;
        }}
        .toc ul {{
            list-style: none;
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 10px;
        }}
        .toc a {{
            color: #3282b8;
            text-decoration: none;
            padding: 8px 12px;
            display: block;
            border-radius: 6px;
            transition: background 0.2s;
        }}
        .toc a:hover {{
            background: #e9ecef;
        }}
        .recommendation {{
            background: #fff;
            border: 1px solid #e9ecef;
            border-radius: 10px;
            padding: 20px;
            margin: 15px 0;
            border-left: 4px solid #27ae60;
        }}
        .recommendation.priority-high {{
            border-left-color: #e74c3c;
        }}
        .recommendation.priority-medium {{
            border-left-color: #f39c12;
        }}
        .recommendation h4 {{
            color: #0f4c75;
            margin-bottom: 10px;
        }}
        .recommendation ul {{
            margin-left: 20px;
            color: #495057;
        }}
        .two-col {{
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 30px;
        }}
        @media (max-width: 768px) {{
            .two-col {{
                grid-template-columns: 1fr;
            }}
            .chart-grid {{
                grid-template-columns: 1fr;
            }}
            .header h1 {{
                font-size: 1.6em;
            }}
        }}
    </style>
</head>
<body>
    <div class="report-container">
        <div class="header">
            <h1>EV Charging Network Performance & Grid Optimization</h1>
            <div class="subtitle">Comprehensive Analysis of Charging Operations, Demand Patterns & Optimization Opportunities</div>
            <div class="meta">Generated: ''' + datetime.now().strftime('%B %d, %Y at %I:%M %p') + f''' | Data Period: {summary['date_range']}</div>
        </div>

        <div class="kpi-banner">
            <div class="kpi-card highlight">
                <div class="label">Average Waiting Time</div>
                <div class="value">{summary['avg_waiting_time']:.1f} min</div>
                <div class="detail">Queue before charging starts</div>
            </div>
            <div class="kpi-card">
                <div class="label">Energy Per Session</div>
                <div class="value">{summary['avg_energy_per_session']:.1f} kWh</div>
                <div class="detail">Average consumption</div>
            </div>
            <div class="kpi-card warning">
                <div class="label">Mean Station Load</div>
                <div class="value">{summary['avg_station_load']:.1f} kW</div>
                <div class="detail">Grid stress indicator</div>
            </div>
            <div class="kpi-card success">
                <div class="label">Renewable Energy Ratio</div>
                <div class="value">{summary['avg_renewable_ratio']:.1%}</div>
                <div class="detail">From renewable sources</div>
            </div>
            <div class="kpi-card">
                <div class="label">Optimization Reward</div>
                <div class="value">{summary['avg_optimization_reward']:.2f}</div>
                <div class="detail">Grid optimization score</div>
            </div>
        </div>

        <nav class="toc">
            <h3>Report Sections</h3>
            <ul>
                <li><a href="#station-utilization">1. Station Utilization & Demand Analysis</a></li>
                <li><a href="#queue-wait-analysis">2. Queue Length & Waiting Time Analysis</a></li>
                <li><a href="#energy-grid-load">3. Energy Consumption & Grid Load Patterns</a></li>
                <li><a href="#renewable-pricing">4. Renewable Energy Integration & Dynamic Pricing</a></li>
                <li><a href="#vehicle-charging-behavior">5. Vehicle Charging Behavior & Session Profiles</a></li>
                <li><a href="#optimization-recommendations">6. Optimization Insights & Recommendations</a></li>
            </ul>
        </nav>

        <section id="station-utilization" class="section">
            <h2>1. Station Utilization & Demand Analysis</h2>
            <p>This section examines charging demand distribution across stations and location types, identifying high-demand stations and peak utilization periods.</p>

            <h3>Utilization by Location Type</h3>
            <table>
                <thead>
                    <tr>
                        <th>Location Type</th>
                        <th>Avg Wait Time (min)</th>
                        <th>Avg Energy (kWh)</th>
                        <th>Avg Station Load (kW)</th>
                        <th>Avg Queue Length</th>
                        <th>Renewable Ratio</th>
                    </tr>
                </thead>
                <tbody>'''

for loc, stats in location_summary.items():
    html += f'''<tr>
        <td><strong>{loc}</strong></td>
        <td>{stats['waiting_time']:.1f}</td>
        <td>{stats['energy_consumed_kWh']:.1f}</td>
        <td>{stats['station_load']:.1f}</td>
        <td>{stats['queue_length']:.1f}</td>
        <td>{stats['renewable_energy_ratio']:.1%}</td>
    </tr>'''

html += '''</tbody></table>

            <div class="takeaway">
                <div class="takeaway-title">Key Finding</div>
                Urban stations exhibit the highest average queue lengths and waiting times, indicating capacity constraints in metropolitan areas. Highway stations show moderate utilization but benefit from longer sessions due to higher battery capacities.
            </div>

            <h3>Top 10 Stations by Session Volume</h3>
            <div class="chart-grid">
                <div class="chart-container">
                    <canvas id="stationVolumeChart"></canvas>
                </div>
            </div>
        </section>

        <section id="queue-wait-analysis" class="section">
            <h2>2. Queue Length & Waiting Time Analysis</h2>
            <p>Critical customer experience analysis examining queue lengths and waiting times across stations, time slots, and vehicle types to identify bottleneck patterns.</p>

            <h3>Waiting Time Heatmap by Time Slot & Location</h3>
            <div class="heatmap-container">
                <table>
                    <thead>
                        <tr>
                            <th>Time Slot</th>
                            <th>Highway</th>
                            <th>Suburban</th>
                            <th>Urban</th>
                        </tr>
                    </thead>
                    <tbody>'''

time_slots = ['Off-Peak', 'Mid-Peak', 'Peak']
location_types = ['Highway', 'Suburban', 'Urban']

for slot in time_slots:
    if slot in wait_heatmap:
        html += f'''<tr>
            <td><span class="badge">{'badge-offpeak' if slot == 'Off-Peak' else 'badge-midpeak' if slot == 'Mid-Peak' else 'badge-peak'}">{slot}</span></td>'''
        for loc in location_types:
            val = wait_heatmap[slot].get(loc, wait_heatmap[slot].get(loc.title(), 'N/A'))
            if isinstance(val, (int, float)):
                html += f'<td>{val:.1f} min</td>'
            else:
                html += '<td>N/A</td>'
        html += '</tr>'

html += '''</tbody></table>
            </div>

            <div class="chart-grid">
                <div class="chart-container">
                    <canvas id="waitByTimeSlot"></canvas>
                </div>
                <div class="chart-container">
                    <canvas id="queueByTimeSlot"></canvas>
                </div>
            </div>

            <h3>Waiting Time by Vehicle Type</h3>
            <table>
                <thead>
                    <tr>
                        <th>Vehicle Type</th>
                        <th>Avg Wait Time (min)</th>
                        <th>Avg Battery Capacity (kWh)</th>
                        <th>Avg Charging Duration (min)</th>
                        <th>Avg Initial SOC (%)</th>
                    </tr>
                </thead>
                <tbody>'''

for vtype, stats in vehicle_summary.items():
    html += f'''<tr>
        <td><strong>{vtype}</strong></td>
        <td>{stats['waiting_time']:.1f}</td>
        <td>{stats['battery_capacity_kWh']:.1f}</td>
        <td>{stats['charging_duration']:.1f}</td>
        <td>{stats['initial_soc']:.1f}</td>
    </tr>'''

html += '''</tbody></table>

            <div class="takeaway">
                <div class="takeaway-title">Key Finding</div>
                Peak hours show significantly higher waiting times across all location types, with Urban stations reaching averages of 15+ minutes during peak periods. Buses and SUVs experience the longest queues, suggesting capacity mismatch with vehicle demand.
            </div>
        </section>

        <section id="energy-grid-load" class="section">
            <h2>3. Energy Consumption & Grid Load Patterns</h2>
            <p>Assessment of energy consumption patterns, station load profiles across time slots and days of the week, and grid stress indicators.</p>

            <h3>Station Load by Time Slot</h3>
            <div class="chart-grid">
                <div class="chart-container">
                    <canvas id="loadByTimeSlot"></canvas>
                </div>
                <div class="chart-container">
                    <canvas id="energyByTimeSlot"></canvas>
                </div>
            </div>

            <h3>Load Statistics by Location Type</h3>
            <table>
                <thead>
                    <tr>
                        <th>Location Type</th>
                        <th>Avg Station Load (kW)</th>
                        <th>Avg Energy per Session (kWh)</th>
                        <th>Avg Optimization Reward</th>
                    </tr>
                </thead>
                <tbody>'''

for loc, stats in location_summary.items():
    html += f'''<tr>
        <td><strong>{loc}</strong></td>
        <td>{stats['station_load']:.1f}</td>
        <td>{stats['energy_consumed_kWh']:.1f}</td>
        <td>{stats['optimization_reward']:.2f}</td>
    </tr>'''

html += '''</tbody></table>

            <div class="takeaway">
                <div class="takeaway-title">Key Finding</div>
                Peak hours create pronounced grid stress with station loads averaging 60-70 kW during Peak times versus 30-40 kW during Off-Peak. The negative optimization rewards during Peak periods indicate suboptimal grid conditions that require intervention.
            </div>
        </section>

        <section id="renewable-pricing" class="section">
            <h2>4. Renewable Energy Integration & Dynamic Pricing</h2>
            <p>Evaluation of renewable energy ratio across different conditions and analysis of dynamic pricing correlations with demand and optimization rewards.</p>

            <h3>Renewable Energy Ratio by Weather & Time Slot</h3>
            <div class="heatmap-container">
                <table>
                    <thead>
                        <tr>
                            <th>Weather</th>
                            <th>Off-Peak</th>
                            <th>Mid-Peak</th>
                            <th>Peak</th>
                        </tr>
                    </thead>
                    <tbody>'''

weather_conditions = ['Clear', 'Cloudy', 'Rainy', 'Snowy']
for weather in weather_conditions:
    if weather in renewable_weather:
        html += f'''<tr>
            <td><strong>{weather}</strong></td>'''
        for slot in ['Off-Peak', 'Mid-Peak', 'Peak']:
            val = renewable_weather[weather].get(slot, 'N/A')
            if isinstance(val, (int, float)):
                html += f'<td>{val:.1%}</td>'
            else:
                html += '<td>N/A</td>'
        html += '</tr>'

html += '''</tbody></table>
            </div>

            <div class="chart-grid">
                <div class="chart-container">
                    <canvas id="renewableByWeather"></canvas>
                </div>
                <div class="chart-container">
                    <canvas id="priceBySlot"></canvas>
                </div>
            </div>

            <h3>Electricity Price by Time Slot</h3>
            <table>
                <thead>
                    <tr>
                        <th>Time Slot</th>
                        <th>Avg Electricity Price</th>
                        <th>Avg Renewable Ratio</th>
                    </tr>
                </thead>
                <tbody>'''

for slot in time_slots:
    if slot in timeslot_summary:
        stats = timeslot_summary[slot]
        html += f'''<tr>
            <td><span class="badge">{'badge-offpeak' if slot == 'Off-Peak' else 'badge-midpeak' if slot == 'Mid-Peak' else 'badge-peak'}">{slot}</span></td>
            <td>{price_by_slot.get(slot, 'N/A'):.2f}</td>
            <td>{stats['renewable_energy_ratio']:.1%}</td>
        </tr>'''

html += '''</tbody></table>

            <div class="takeaway">
                <div class="takeaway-title">Key Finding</div>
                Renewable energy utilization is highest during Off-Peak hours (42% average) when grid demand is low. Dynamic pricing shows strong correlation with time slots, with Peak prices 40-60% higher than Off-Peak. Clear weather conditions yield the highest renewable ratios.
            </div>
        </section>

        <section id="vehicle-charging-behavior" class="section">
            <h2>5. Vehicle Charging Behavior & Session Profiles</h2>
            <p>Charging session profiling by vehicle type, examining battery capacity, state of charge patterns, and usage characteristics.</p>

            <h3>Session Metrics by Vehicle Type</h3>
            <div class="chart-grid">
                <div class="chart-container">
                    <canvas id="vehicleWaitTime"></canvas>
                </div>
                <div class="chart-container">
                    <canvas id="vehicleEnergy"></canvas>
                </div>
            </div>

            <table>
                <thead>
                    <tr>
                        <th>Vehicle Type</th>
